package com.ruoyi.paismart.application.intelligence;

import com.ruoyi.common.exception.ServiceException;
import com.ruoyi.paismart.application.MembershipService;
import com.ruoyi.paismart.application.documents.DocumentService;
import com.ruoyi.paismart.application.spaces.SpaceService;
import com.ruoyi.paismart.infrastructure.Jsons;
import com.ruoyi.paismart.infrastructure.intelligence.*;
import com.ruoyi.system.secret.ManagedSecretService;
import java.sql.Connection;
import java.util.*;
import java.util.concurrent.*;
import org.h2.jdbcx.JdbcDataSource;
import org.junit.jupiter.api.*;
import org.springframework.core.io.ClassPathResource;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.init.ScriptUtils;
import org.springframework.mock.env.MockEnvironment;
import org.springframework.test.util.ReflectionTestUtils;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

/** 复用原双路/降级与父块固定样例；ES和模型全部为本地替身。 */
class SearchRetrievalBoundaryTest {
    JdbcTemplate db;SearchService service;MockEnvironment env;DocumentService docs;ModelGateway models;ControlledHttp http;ProviderService providers;ExecutorService executor;SpaceService.Scope scope=new SpaceService.Scope(2,false);
    Map<String,Object> index=Map.of("index_name","paismart-knowledge-test","provider_snapshot","{}");
    @BeforeEach void prepare() throws Exception {var source=new JdbcDataSource();source.setURL("jdbc:h2:mem:recall_"+UUID.randomUUID()+";MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1");try(Connection c=source.getConnection()){ScriptUtils.executeSqlScript(c,new ClassPathResource("db/paismart/V003__intelligence.sql"));ScriptUtils.executeSqlScript(c,new ClassPathResource("db/paismart/V005__evaluation_datasets.sql"));}db=new JdbcTemplate(source);env=new MockEnvironment().withProperty("paismart.intelligence.elasticsearch.endpoint","https://es.invalid");docs=mock(DocumentService.class);models=mock(ModelGateway.class);http=mock(ControlledHttp.class);providers=mock(ProviderService.class);var spaces=mock(SpaceService.class);when(spaces.visibleSpaceIds(any())).thenReturn(Set.of("org"));service=new SearchService(db,http,new IntelligenceSettings(env,mock(ManagedSecretService.class)),providers,models,spaces,docs);ReflectionTestUtils.setField(service,"members",mock(MembershipService.class));when(http.json(eq("GET"),endsWith("/_mapping"),nullable(String.class),isNull(),anyInt())).thenReturn(Map.of("paismart-knowledge-test",Map.of("mappings",Map.of("properties",Map.of("text_content",Map.of("type","text"))))));executor=Executors.newFixedThreadPool(2);ReflectionTestUtils.setField(service,"recallExecutor",executor);when(models.embed(anyLong(),anyString(),anyList(),any())).thenReturn(new ModelGateway.Embedding(List.of(List.of(.1,.2)),2));}
    @AfterEach void close(){executor.shutdownNow();}
    @Test void recallWindowNeverFallsBelowRequestedTopKEvenWhenConfiguredMaximumIsSmaller(){
        env.setProperty("paismart.intelligence.hybrid.max-recall-window","10");when(http.json(eq("POST"),anyString(),nullable(String.class),any(),eq(10))).thenAnswer(i->{Map<?,?> body=i.getArgument(3);assertEquals(20,body.get("size"));if(body.containsKey("knn"))assertEquals(20,((Map<?,?>)body.get("knn")).get("k"));return hits();});assertTrue(service.searchAt(scope,"问题",20,null,index).rows().isEmpty());verify(http,times(2)).json(eq("POST"),anyString(),nullable(String.class),any(),eq(10));
    }
    @Test void contextualSwitchSelectsActualRawFieldEvenWhenPriorProjectionRetainsExplanation(){
        chunk("doc",0,"原文");db.update("UPDATE ps_document_chunk SET context_text='仅背景词'");List<String> fields=Collections.synchronizedList(new ArrayList<>());
        when(http.json(eq("POST"),anyString(),nullable(String.class),any(),anyInt())).thenAnswer(i->{Map<?,?> body=i.getArgument(3);if(body.containsKey("knn"))return hits();Map<?,?> query=(Map<?,?>)body.get("query"),bool=(Map<?,?>)query.get("bool"),match=(Map<?,?>)((Map<?,?>)((List<?>)bool.get("must")).get(0)).get("match");String field=match.keySet().iterator().next().toString();fields.add(field);return "search_text".equals(field)?hits("doc0"):hits();});
        env.setProperty("paismart.intelligence.contextual-enabled","true");assertEquals(1,service.searchAt(scope,"仅背景词",5,null,index).rows().size());env.setProperty("paismart.intelligence.contextual-enabled","false");assertTrue(service.searchAt(scope,"仅背景词",5,null,index).rows().isEmpty());assertEquals(List.of("search_text","text_content"),fields);
    }
    @Test void legacyProjectionMissingRawFieldRequiresRebuildBeforeAnyPaidEmbeddingOrFakeEmptyResult(){
        when(http.json(eq("GET"),endsWith("/_mapping"),nullable(String.class),isNull(),anyInt())).thenReturn(Map.of("paismart-knowledge-test",Map.of("mappings",Map.of("properties",Map.of("search_text",Map.of("type","text"))))));var failure=assertThrows(IllegalStateException.class,()->service.searchAt(scope,"问题",5,null,index));assertTrue(failure.getMessage().contains("INDEX_REBUILD_REQUIRED"));verifyNoInteractions(models);verify(http,never()).json(eq("POST"),anyString(),nullable(String.class),any(),anyInt());
    }
    SearchService.Evidence chunk(String doc,int no,String text) {String id=doc+no;db.update("INSERT INTO ps_document_chunk(id,document_id,content_version,chunk_no,page_no,text_content,anchor_text,created_at) VALUES(?,?,1,?,?,?,'anchor',CURRENT_TIMESTAMP)",id,doc,no,no+1,text);var d=mock(DocumentService.Document.class);when(d.id()).thenReturn(doc);when(d.contentVersion()).thenReturn(1);when(d.state()).thenReturn("READY");when(d.title()).thenReturn(doc+".pdf");when(docs.getReadable(any(),eq(doc))).thenReturn(d);return new SearchService.Evidence(id,doc,1,no,no+1,doc+".pdf",text,"anchor","",.9,"RRF");}
    Map<String,Object> hits(String... ids){return Map.of("hits",Map.of("hits",Arrays.stream(ids).map(id->Map.of("_id",id,"_score",.8)).toList()));}
    void dual(){when(http.json(eq("POST"),anyString(),nullable(String.class),any(),anyInt())).thenAnswer(i->((Map<?,?>)i.getArgument(3)).containsKey("knn")?hits("both1","vec2"):hits("kw0","both1"));}
    @Test void embeddingFailureReturnsAuthorizedBm25WithItsOwnScoreTypeAndMinimumScore(){chunk("doc",0,"证据");when(models.embed(anyLong(),anyString(),anyList(),any())).thenThrow(new IllegalStateException("embedding down"));when(http.json(eq("POST"),anyString(),nullable(String.class),any(),anyInt())).thenAnswer(i->{Map<?,?> body=i.getArgument(3);assertEquals(.3,body.get("min_score"));assertFalse(body.containsKey("knn"));assertTrue(Jsons.write(body).contains("owner_id"));assertTrue(Jsons.write(body).contains("org"));return hits("doc0");});var result=service.searchAt(scope,"问题",5,null,index);assertEquals("TEXT_ONLY",result.scoreType());assertEquals(1,result.rows().size());assertFalse(result.degradation().isEmpty());}
    @Test void knnFailureFallsBackToTextInsteadOfFailingWholeQuery(){chunk("doc",0,"证据");when(http.json(eq("POST"),anyString(),nullable(String.class),any(),anyInt())).thenAnswer(i->{Map<?,?> body=i.getArgument(3);if(body.containsKey("knn"))throw new IllegalStateException("knn down");return hits("doc0");});assertEquals("TEXT_ONLY",service.searchAt(scope,"问题",5,null,index).scoreType());}
    @Test void bothEsPathsUnavailableReportFailureInsteadOfFakeEmptySearch(){when(models.embed(anyLong(),anyString(),anyList(),any())).thenThrow(new IllegalStateException("embedding down"));when(http.json(eq("POST"),anyString(),nullable(String.class),any(),anyInt())).thenThrow(new IllegalStateException("ES down"));assertTrue(assertThrows(IllegalStateException.class,()->service.searchAt(scope,"问题",5,null,index)).getMessage().contains("SEARCH_UNAVAILABLE"));}
    @Test void dualRecallRunsIndependentlyWithBoundedWindowAndRrfFallback(){chunk("kw",0,"关键词");chunk("both",1,"两路");chunk("vec",2,"语义");CountDownLatch entered=new CountDownLatch(2);when(http.json(eq("POST"),anyString(),nullable(String.class),any(),eq(10))).thenAnswer(i->{entered.countDown();assertTrue(entered.await(2,TimeUnit.SECONDS));Map<?,?> body=i.getArgument(3);assertEquals(150,body.get("size"));if(body.containsKey("knn")){assertFalse(body.containsKey("query"));assertEquals(300,((Map<?,?>)body.get("knn")).get("num_candidates"));return hits("both1","vec2");}return hits("kw0","both1");});var result=service.searchAt(scope,"问题",5,null,index);assertEquals(List.of("both1","kw0","vec2"),result.rows().stream().map(SearchService.Evidence::id).toList());assertEquals("RRF",result.scoreType());}
    @Test void rerankUsesExplanationAndOriginalButReturnsOnlyOriginalCitation(){env.setProperty("paismart.intelligence.contextual-enabled","true");env.setProperty("paismart.intelligence.rerank-enabled","true");chunk("doc",0,"原文");db.update("UPDATE ps_document_chunk SET context_text='说明'");when(http.json(eq("POST"),anyString(),nullable(String.class),any(),anyInt())).thenReturn(hits("doc0"));when(models.rerank(anyLong(),anyString(),eq("问题"),eq(List.of("说明\n\n原文")),any())).thenReturn(Map.of("results",List.of(Map.of("index",0,"relevance_score",.9))));var result=service.searchAt(scope,"问题",5,null,index);assertEquals("RERANK",result.scoreType());assertEquals("原文",result.rows().get(0).text());assertEquals("说明",result.rows().get(0).context());assertEquals("原文",result.rows().get(0).modelText());}
    @Test void rerankThresholdCanReturnFewerThanTopKAndDoesNotApplyToRrf(){chunk("doc",0,"证据");env.setProperty("paismart.intelligence.rerank-enabled","true");when(http.json(eq("POST"),anyString(),nullable(String.class),any(),anyInt())).thenReturn(hits("doc0"));when(models.rerank(anyLong(),anyString(),anyString(),anyList(),any())).thenReturn(Map.of("results",List.of(Map.of("index",0,"relevance_score",.05))));assertTrue(service.searchAt(scope,"问题",5,null,index).rows().isEmpty());when(models.rerank(anyLong(),anyString(),anyString(),anyList(),any())).thenThrow(new IllegalStateException("down"));assertEquals("RRF",service.searchAt(scope,"问题",5,null,index).scoreType());assertEquals(1,service.searchAt(scope,"问题",5,null,index).rows().size());}
    @Test void parentRetainsEverySmallHitAndReusesExactCoveredRange(){List<SearchService.Evidence> chunks=new ArrayList<>();for(int n=0;n<6;n++)chunks.add(chunk("doc",n,"第"+n+"块。"));env.setProperty("paismart.intelligence.parent-context.max-total-characters","20");var expanded=service.expand(scope,List.of(chunks.get(2),chunks.get(3),chunks.get(5)));assertEquals(3,expanded.size());assertEquals("doc:1#1-3",expanded.get(0).parentKey());assertEquals(expanded.get(0).parentKey(),expanded.get(1).parentKey());assertEquals("",expanded.get(2).parentContext());assertEquals("第3块。",expanded.get(1).text());assertEquals(4,expanded.get(1).page());}
    @Test void parentCapStartsAtHitRatherThanConsumingBudgetOnLongPreviousNeighbor(){chunk("doc",0,"前文".repeat(60));var hit=chunk("doc",1,"命中。" );chunk("doc",2,"后文。");env.setProperty("paismart.intelligence.parent-context.max-characters-per-hit","10");var result=service.expand(scope,List.of(hit)).get(0);assertEquals("命中。\n\n后文。",result.parentContext());assertEquals("doc:1#1-2",result.parentKey());}
    @Test void parentRemovesOverlapAndCanBeDisabled(){chunk("doc",0,"重复句子。");var hit=chunk("doc",1,"重复句子。\n\n新的正文。");chunk("doc",2,"后文。");var result=service.expand(scope,List.of(hit)).get(0);assertEquals("重复句子。\n\n新的正文。\n\n后文。",result.parentContext());env.setProperty("paismart.intelligence.parent-context.enabled","false");assertSame(hit,service.expand(scope,List.of(hit)).get(0));}
    @Test void exhaustedBudgetAndMissingNeighborsPreserveSmallChunks(){var first=chunk("doc",0,"第一块。");var second=chunk("doc",1,"第二块。");env.setProperty("paismart.intelligence.parent-context.max-total-characters","0");assertEquals(List.of(first,second),service.expand(scope,List.of(first,second)));}
    @Test void revokedDocumentNeverReentersParentEvidence(){var hit=chunk("doc",0,"证据");when(docs.getReadable(any(),eq("doc"))).thenThrow(new ServiceException("无权访问",403));assertTrue(service.expand(scope,List.of(hit)).isEmpty());}

    @Test void conflictKnnRecoversCosineThresholdDeduplicatesAndKeepsPermission(){
        chunk("old",0,"证据");db.update("UPDATE ps_document_chunk SET embedding_revision='idx'");db.update("INSERT INTO ps_index_revision(id,index_name,provider_snapshot,state,created_at,updated_at) VALUES('idx','paismart-knowledge-test','{}','ACTIVE',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)");
        when(http.json(eq("POST"),anyString(),nullable(String.class),any(),eq(90))).thenAnswer(i->{Map<?,?> body=i.getArgument(3),knn=(Map<?,?>)body.get("knn");assertEquals(3,knn.get("k"));assertEquals(100,knn.get("num_candidates"));String filter=Jsons.write(knn.get("filter"));assertTrue(filter.contains("owner_id"));assertTrue(filter.contains("embedding_revision"));assertTrue(filter.contains("must_not"));return Map.of("hits",Map.of("hits",List.of(Map.of("_id","old0","_score",.944999),Map.of("_id","old0","_score",.975),Map.of("_id","old0","_score",.975))));});
        var result=service.conflictCandidates(scope,"new",List.of(.1,.2));assertEquals(1,result.size());assertEquals(.95,(Double)result.get(0).get("cosineSimilarity"),1e-9);assertEquals(0,SearchService.cosineFromScore(null));assertEquals(.95,SearchService.cosineFromScore(.975),1e-9);
    }
    @Test void lowCosineOrRevokedConflictEvidenceIsNotReturned(){
        chunk("old",0,"证据");db.update("UPDATE ps_document_chunk SET embedding_revision='idx'");db.update("INSERT INTO ps_index_revision(id,index_name,provider_snapshot,state,created_at,updated_at) VALUES('idx','paismart-knowledge-test','{}','ACTIVE',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)");
        when(http.json(eq("POST"),anyString(),nullable(String.class),any(),eq(90))).thenReturn(Map.of("hits",Map.of("hits",List.of(Map.of("_id","old0","_score",.94499)))));assertTrue(service.conflictCandidates(scope,"new",List.of(.1,.2)).isEmpty());
        when(http.json(eq("POST"),anyString(),nullable(String.class),any(),eq(90))).thenReturn(Map.of("hits",Map.of("hits",List.of(Map.of("_id","old0","_score",.99)))));when(docs.getReadable(any(),eq("old"))).thenThrow(new ServiceException("无权读取",403));assertTrue(service.conflictCandidates(scope,"new",List.of(.1,.2)).isEmpty());
    }
}
